    protected PriceDisc createPriceDiscInstance(PriceDiscParameters _parameters)
    {
        PriceDisc priceDisc = next createPriceDiscInstance(_parameters);
        SalesPurchLineInterface salesPurchLineInterface = SalesPurchLineInterface::createInstance(this.getSalesLine());
        priceDisc.parmSalesPurchLineInterface(salesPurchLineInterface);

        return priceDisc;
    }
